#[no_mangle]
pub unsafe extern "C" fn nzbget_rs_dsp_match_servers(
    server_names: *const *const c_char,
    server_hosts: *const *const c_char,
    server_ports: *const c_int,
    server_users: *const *const c_char,
    server_count: usize,
    ref_state_ids: *const c_int,
    ref_names: *const *const c_char,
    ref_hosts: *const *const c_char,
    ref_ports: *const c_int,
    ref_users: *const *const c_char,
    ref_count: usize,
    out_server_state_ids: *mut c_int,
) -> c_int {
    if server_count > 0
        && (server_names.is_null()
            || server_hosts.is_null()
            || server_ports.is_null()
            || server_users.is_null()
            || out_server_state_ids.is_null())
    {
        return 0;
    }
    if ref_count > 0
        && (ref_state_ids.is_null()
            || ref_names.is_null()
            || ref_hosts.is_null()
            || ref_ports.is_null()
            || ref_users.is_null())
    {
        return 0;
    }

    let mut servers = Vec::with_capacity(server_count);
    for i in 0..server_count {
        servers.push(crate::diskstate_format::ServerMatchInput {
            name: crate::diskstate_format::cstr_to_bytes(*server_names.add(i)),
            host: crate::diskstate_format::cstr_to_bytes(*server_hosts.add(i)),
            port: *server_ports.add(i),
            user: crate::diskstate_format::cstr_to_bytes(*server_users.add(i)),
        });
    }

    let mut refs = Vec::with_capacity(ref_count);
    for i in 0..ref_count {
        refs.push(crate::diskstate_format::ServerRefEntry {
            state_id: *ref_state_ids.add(i),
            name: crate::diskstate_format::cstr_to_bytes(*ref_names.add(i)),
            host: crate::diskstate_format::cstr_to_bytes(*ref_hosts.add(i)),
            port: *ref_ports.add(i),
            user: crate::diskstate_format::cstr_to_bytes(*ref_users.add(i)),
            matched: false,
            perfect: false,
        });
    }

    let out_ids = if server_count == 0 {
        &mut [][..]
    } else {
        std::slice::from_raw_parts_mut(out_server_state_ids, server_count)
    };
    if crate::diskstate_format::match_servers(&servers, &mut refs, out_ids) {
        1
    } else {
        0
    }
}

