pub unsafe extern "C" fn nzbget_rs_dqh_mem_slices_equal(
    a: *const u8,
    b: *const u8,
    len: usize,
) -> c_int {
    if len == 0 {
        return 1;
    }
    if a.is_null() || b.is_null() {
        return i32::from(a == b);
    }
    let sa = std::slice::from_raw_parts(a, len);
    let sb = std::slice::from_raw_parts(b, len);
    i32::from(crate::util::mem_slices_equal(sa, sb))
}

