#[no_mangle]
pub unsafe extern "C" fn nzbget_rs_dqh_xmlrpc_calc_schedule_resume_time(
    has_param: c_int,
    seconds: c_int,
    cur_time: i64,
    out_resume_time: *mut i64,
) -> c_int {
    match crate::xmlrpc_format::xmlrpc_calc_schedule_resume_time(
        has_param != 0,
        seconds,
        cur_time,
    ) {
        Some(t) => {
            if !out_resume_time.is_null() {
                *out_resume_time = t;
            }
            1
        }
        None => 0,
    }
}

