// End-to-End MoveController, CleanupController, and RenameController FFI
// =========================================================================

fn bytes_to_cstr_buf(bytes: &[u8]) -> Vec<u8> {
    let mut buf = Vec::with_capacity(bytes.len() + 1);
    for &b in bytes {
        if b != 0 {
            buf.push(b);
        }
    }
    buf.push(0);
    buf
}

